    ),
    "child_under_5": (
        "Child and caregiver pathway", "Age-aware history for children under five, guided by the caregiver.",
        "child_care", "green",
    ),
    "infant_under_2_months": (
        "Young infant pathway", "Infant-focused history. Record age in days or weeks when known.",
